            current, path = queue.pop(0)
            if current == end:
                return path
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = current[0] + dr, current[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    new_path = path + [(nr, nc)]
                    queue.append(( (nr, nc), new_path ))
        return []

    # Bidirectional search: start from both start and goal
    # and meet in the middle
    def bidirectional_bfs(start, goal):
        from collections import deque

        # BFS from start
        start_queue = deque()
        start_queue.append( (start, [start]) )
        start_visited = set()
        start_visited.add(start)

        # BFS from goal
        goal_queue = deque()
        goal_queue.append( (goal, [goal]) )
        goal_visited = set()
        goal_visited.add(goal)

        while start_queue and goal_queue:
            # BFS from start
            current, path = start_queue.popleft()
            if current in goal_visited:
                return path
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = current[0] + dr, current[1] + dc
                if is_valid(nr, nc) and (nr, nc) not in start_visited:
