def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0])

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    # Keep track of visited cells
    visited = set()
    # Use a stack for DFS
    stack = [(start[0], start[1], 0, 0)]  # (row, col, direction index, path)

    while stack:
        r, c, dir_idx, path = stack.pop()
        if (r, c) == goal:
            return path
        visited.add((r, c))

        # Try each direction in order
        for i in range(4):
            dr, dc = directions[i]
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                # Check if this direction is the first in the sequence
                if i == 0 or i == 2 or i == 3:
                    # If the previous direction was not the opposite, proceed
                    if i == 0 and dir_idx != 2:
                        stack.append((nr, nc, i, path + [(nr, nc)]))
                    elif i == 2 and dir_idx != 0:
                        stack.append((nr, nc, i, path + [(nr, nc)]))
                    elif i == 3 and dir_idx != 1:
                        stack.append((nr, nc, i, path + [(nr, nc)]))
                else:
                    # If the previous direction was not the opposite, proceed
                    if i == 1 and dir_idx != 3:
                        stack.append((nr, nc, i, path + [(nr, nc)]))
    return []
