def solve(grid, start, goal):
    if start == goal:
        return [start]

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Initialize a visited matrix to track visited cells
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = []

    def wall_follower(r, c, dir_idx):
        # Check if current cell is a wall
        if grid[r][c] == '#':
            return False

        # Mark current cell as visited
        visited[r][c] = True
        path.append((r, c))

        # Check if we've reached the goal
        if (r, c) == goal:
            return True

        # Try to move in the current direction
        dr, dc = directions[dir_idx]
        new_r, new_c = r + dr, c + dc
        if 0 <= new_r < rows and 0 <= new_c < cols and not visited[new_r][new_c] and grid[new_r][new_c] == '.':
            if wall_follower(new_r, new_c, dir_idx):
                return True

        # If movement in current direction is blocked, try the next direction
        for i in range(dir_idx + 1, 4):
            dr, dc = directions[i]
            new_r, new_c = r + dr, c + dc
            if 0 <= new_r < rows and 0 <= new_c < cols and not visited[new_r][new_c] and grid[new_r][new_c] == '.':
                if wall_follower(new_r, new_c, i):
                    return True

        # If no path found from this direction, backtrack
        path.pop()
        return False

    if wall_follower(start[0], start[1], 0):
        return path
    else:
        return []

