def solve(grid, start, goal):
    import sys
    sys.setrecursionlimit(10000)

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    if start == goal:
        return [start]

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Use Bellman-Ford style sweep relaxation
    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0

    for _ in range(rows * cols):
        updated = False
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == '#':
                    continue
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == '.':
                        if dist[ni][nj] > dist[i][j] + 1:
                            dist[ni][nj] = dist[i][j] + 1
                            updated = True
        if not updated:
            break

    # Reconstruct path
    if dist[goal[0]][goal[1]] == float('inf'):
        return []

    path = []
    x, y = goal
    while (x, y) != start:
        path.append((x, y))
        next_x, next_y = -1, -1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and dist[nx][ny] == dist[x][y] - 1:
                next_x, next_y = nx, ny
                break
        x, y = next_x, next_y
    path.append(start)
    return path[::-1]
