def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Initialize distance matrix with infinity
    distance = [[float('inf')] * cols for _ in range(rows)]
    # Initialize predecessor matrix
    predecessor = [[None] * cols for _ in range(rows)]

    # Set distance of start to 0
    distance[start[0]][start[1]] = 0

    # Bellman-Ford style relaxation
    for i in range(rows * cols):
        updated = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#':
                    continue
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        if distance[nr][nc] > distance[r][c] + 1:
                            distance[nr][nc] = distance[r][c] + 1
                            predecessor[nr][nc] = (r, c)
                            updated = True
        if not updated:
            break

    # Reconstruct path
    if distance[goal[0]][goal[1]] == float('inf'):
        return []

    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = predecessor[current[0]][current[1]]

    return path[::-1]
