    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is a wall or out of bounds
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # Check if start == goal
    if start == goal:
        return [start]

    # Initialize distance matrix with infinity
    distance = [[float('inf')] * cols for _ in range(rows)]
    distance[start[0]][start[1]] = 0

    # Bellman-Ford style sweep relaxation
    for i in range(rows * cols):
        updated = False
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == '#':
                    continue
                # Check all four directions
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.':
                        if distance[nr][nc] > distance[r][c] + 1:
                            distance[nr][nc] = distance[r][c] + 1
                            updated = True
        if not updated:
            break

    # Reconstruct path
    if distance[goal[0]][goal[1]] == float('inf'):
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        # Find predecessor with minimum distance
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = current[0] + dr, current[1] + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and distance[nr][nc] == distance[current[0]][current[1]] - 1:
                current = (nr, nc)
                break
    path.append(start)
    path.reverse()
    return path
