def solve(grid, start, goal):
    from collections import deque

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Initialize distance to all cells as infinity
    dist = [[float('inf')] * cols for _ in range(rows)]
    dist[start[0]][start[1]] = 0

    # Use a priority queue for Bellman-Ford style relaxation
    # Here, we use a deque for a BFS-like approach, but it's not strictly BFS
    # This is a relaxation method similar to Bellman-Ford
    # We'll do this for V-1 times where V is the number of nodes
    for _ in range(rows * cols):
        updated = False
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == '#':
                    continue
                for dx, dy in directions:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == '.':
                        if dist[ni][nj] > dist[i][j] + 1:
                            dist[ni][nj] = dist[i][j] + 1
                            updated = True
        if not updated:
            break

    # Reconstruct path
    if dist[goal[0]][goal[1]] == float('inf'):
        return []

    # Use BFS to reconstruct the path
    prev = [[None] * cols for _ in range(rows)]
    queue = deque()
    queue.append(goal)
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == '.' and dist[nx][ny] == dist[x][y] - 1:
                prev[nx][ny] = (x, y)
                queue.append((nx, ny))
                if (nx, ny) == start:
                    break

    # Reconstruct the path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = prev[current[0]][current[1]]
    path.reverse()

    return path

