def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Check if start or goal is out of bounds or a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Create a 2D array to store the path
    path = [[None for _ in range(cols)] for _ in range(rows)]
    # Create a 2D array to store the distance (or a boolean for reachability)
    dist = [[float('inf')] * cols for _ in range(rows)]

    # Initialize the distance for the start position
    dist[start[0]][start[1]] = 0

    # Floyd-Warshall algorithm
    for k in range(rows):
        for i in range(rows):
            for j in range(cols):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Check if goal is reachable
    if dist[goal[0]][goal[1]] == float('inf'):
        return []

    # Reconstruct the path using BFS (since Floyd-Warshall only gives shortest path distances, not actual path)
    # We need to modify the algorithm to track the path
    # So instead of Floyd-Warshall, we'll use BFS to find a path

    from collections import deque

    def bfs():
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        queue = deque()
        queue.append((start[0], start[1]))
        visited[start[0]][start[1]] = True
        parent = [[None for _ in range(cols)] for _ in range(rows)]

        while queue:
            r, c = queue.popleft()
            if (r, c) == goal:
                break
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == '.':
                    visited[nr][nc] = True
                    parent[nr][nc] = (r, c)
                    queue.append((nr, nc))
        # Reconstruct path
        path = []
        current = goal
        while current:
            path.append(current)
            current = parent[current[0]][current[1]]
        return path[::-1] if path else []

    return bfs()

